    // MARK: - Helpers

    private func makeState(threshold: Double = 0.25) -> DetectionState {
        DetectionState(
            presenceThreshold: threshold,
            absenceThreshold: threshold * 0.6,
            presenceMeasurementsToStartDetection: 2,
            absenceMeasurementsToEndDetection: 8
        )
    }

    private func advance(_ state: DetectionState, confidence: Double) -> DetectionState {
        DetectionState(advancedFrom: state, currentConfidence: confidence)
    }

    // MARK: - Detection Trigger

    func testNoDetectionAfterSingleFrame() {
        var state = makeState(threshold: 0.25)
        state = advance(state, confidence: 0.8)
        XCTAssertFalse(state.isDetected, "Should not detect after only 1 above-threshold frame")
    }

    func testDetectionAfterTwoConsecutiveFrames() {
        var state = makeState(threshold: 0.25)
        state = advance(state, confidence: 0.8)
        state = advance(state, confidence: 0.8)
        XCTAssertTrue(state.isDetected, "Should detect after 2 consecutive above-threshold frames")
    }

    func testSustainedHighConfidenceDetectsIn2Frames() {
        var state = makeState(threshold: 0.25)
        state = advance(state, confidence: 0.7)
        state = advance(state, confidence: 0.7)
        XCTAssertTrue(state.isDetected)
    }

    // MARK: - False Positive Prevention

    func testSingleFrameSpikeRejected() {
        var state = makeState(threshold: 0.25)
        state = advance(state, confidence: 0.9) // spike
        state = advance(state, confidence: 0.0) // drop
        XCTAssertFalse(state.isDetected, "Single-frame spike should not trigger detection")
    }

    func testNoiseSpikeDoesNotTriggerWithoutConsecutivePresence() {
        var state = makeState(threshold: 0.25)
        // Sequence: [0.05, 0.35, 0.08, 0.06] — noise with one spike
        state = advance(state, confidence: 0.05)
        state = advance(state, confidence: 0.35)
        state = advance(state, confidence: 0.08)
        state = advance(state, confidence: 0.06)
        XCTAssertFalse(state.isDetected, "Single spikes should not trigger without consecutive presence")
    }

    func testZeroConfidenceNeverTriggers() {
        var state = makeState(threshold: 0.25)
        for _ in 0..<20 {
            state = advance(state, confidence: 0.0)
        }
        XCTAssertFalse(state.isDetected)
    }

    // MARK: - Counter Stability

    func testCounterResetsWhenSignalDropsBelowThreshold() {
        var state = makeState(threshold: 0.25)
        // Dip below threshold should reset progress; two later highs are needed.
        state = advance(state, confidence: 0.58)
        state = advance(state, confidence: 0.12)
        state = advance(state, confidence: 0.45)
        XCTAssertFalse(state.isDetected)

